import os
import json
from typing import Any, Dict, List, Optional

from google.cloud import documentai_v1 as documentai
from google.api_core.client_options import ClientOptions


STANDARD_SCHEMA = {
    "document_type": None,
    "vendor_name": None,
    "invoice_number": None,
    "receipt_number": None,
    "purchase_order": None,
    "currency": None,
    "invoice_date": None,
    "due_date": None,
    "payment_terms": None,
    "subtotal": None,
    "tax": None,
    "tip": None,
    "shipping": None,
    "discount": None,
    "total": None,
    "amount_paid": None,
    "balance_due": None,
    "payment_method": None,
    "merchant_address": {
        "raw": None,
        "street": None,
        "city": None,
        "state": None,
        "postal_code": None,
        "country": None,
    },
    "merchant_phone": None,
    "merchant_email": None,
    "merchant_website": None,
    "line_items": [],
    "tax_details": [],
    "notes": None,
    "raw_entities": [],
}


ENTITY_KEY_MAP = {
    "supplier_name": "vendor_name",
    "vendor_name": "vendor_name",
    "merchant_name": "vendor_name",
    "invoice_id": "invoice_number",
    "invoice_number": "invoice_number",
    "receipt_id": "receipt_number",
    "receipt_number": "receipt_number",
    "po_number": "purchase_order",
    "purchase_order": "purchase_order",
    "currency": "currency",
    "invoice_date": "invoice_date",
    "receipt_date": "invoice_date",
    "due_date": "due_date",
    "payment_terms": "payment_terms",
    "net_amount": "subtotal",
    "subtotal": "subtotal",
    "tax_amount": "tax",
    "total_tax_amount": "tax",
    "tip_amount": "tip",
    "shipping_amount": "shipping",
    "discount_amount": "discount",
    "total_amount": "total",
    "amount_paid": "amount_paid",
    "balance_due": "balance_due",
    "payment_method": "payment_method",
    "supplier_address": "merchant_address",
    "merchant_address": "merchant_address",
    "supplier_phone": "merchant_phone",
    "merchant_phone": "merchant_phone",
    "supplier_email": "merchant_email",
    "merchant_email": "merchant_email",
    "supplier_website": "merchant_website",
    "merchant_website": "merchant_website",
    "notes": "notes",
}


def _deep_copy_schema() -> Dict[str, Any]:
    return json.loads(json.dumps(STANDARD_SCHEMA))


def _safe_text(entity: documentai.Document.Entity) -> Optional[str]:
    text = (entity.mention_text or "").strip()
    return text or None


def _safe_confidence(entity: documentai.Document.Entity) -> Optional[float]:
    try:
        return float(entity.confidence)
    except Exception:
        return None


def _normalize_number(value: Optional[str]) -> Optional[float]:
    if not value:
        return None
    cleaned = value.strip().replace(",", "")
    allowed = set("0123456789.-")
    cleaned = "".join(ch for ch in cleaned if ch in allowed)
    if not cleaned or cleaned in {"-", ".", "-.", ".-"}:
        return None
    try:
        return float(cleaned)
    except ValueError:
        return None


def _extract_address_parts(address_text: Optional[str]) -> Dict[str, Optional[str]]:
    return {
        "raw": address_text,
        "street": None,
        "city": None,
        "state": None,
        "postal_code": None,
        "country": None,
    }


def _entity_to_raw(entity: documentai.Document.Entity) -> Dict[str, Any]:
    props = []
    for p in entity.properties:
        props.append(
            {
                "type": p.type_,
                "mention_text": (p.mention_text or "").strip() or None,
                "normalized_value": getattr(p.normalized_value, "text", None) if p.normalized_value else None,
                "confidence": _safe_confidence(p),
            }
        )

    normalized_value = None
    if entity.normalized_value:
        normalized_value = {
            "text": getattr(entity.normalized_value, "text", None),
            "money_value": {
                "currency_code": getattr(getattr(entity.normalized_value, "money_value", None), "currency_code", None),
                "units": getattr(getattr(entity.normalized_value, "money_value", None), "units", None),
                "nanos": getattr(getattr(entity.normalized_value, "money_value", None), "nanos", None),
            }
            if getattr(entity.normalized_value, "money_value", None)
            else None,
            "date_value": {
                "year": getattr(getattr(entity.normalized_value, "date_value", None), "year", None),
                "month": getattr(getattr(entity.normalized_value, "date_value", None), "month", None),
                "day": getattr(getattr(entity.normalized_value, "date_value", None), "day", None),
            }
            if getattr(entity.normalized_value, "date_value", None)
            else None,
        }

    return {
        "type": entity.type_,
        "mention_text": _safe_text(entity),
        "confidence": _safe_confidence(entity),
        "normalized_value": normalized_value,
        "properties": props,
    }


def _money_from_entity(entity: documentai.Document.Entity) -> Optional[float]:
    if entity.normalized_value and getattr(entity.normalized_value, "money_value", None):
        mv = entity.normalized_value.money_value
        units = getattr(mv, "units", 0) or 0
        nanos = getattr(mv, "nanos", 0) or 0
        return float(units) + float(nanos) / 1_000_000_000
    if entity.normalized_value and getattr(entity.normalized_value, "text", None):
        parsed = _normalize_number(entity.normalized_value.text)
        if parsed is not None:
            return parsed
    return _normalize_number(_safe_text(entity))


def _date_from_entity(entity: documentai.Document.Entity) -> Optional[str]:
    if entity.normalized_value and getattr(entity.normalized_value, "date_value", None):
        dv = entity.normalized_value.date_value
        year = getattr(dv, "year", 0)
        month = getattr(dv, "month", 0)
        day = getattr(dv, "day", 0)
        if year and month and day:
            return f"{year:04d}-{month:02d}-{day:02d}"
    if entity.normalized_value and getattr(entity.normalized_value, "text", None):
        return entity.normalized_value.text.strip() or None
    return _safe_text(entity)


def _text_from_entity(entity: documentai.Document.Entity) -> Optional[str]:
    if entity.normalized_value and getattr(entity.normalized_value, "text", None):
        text = entity.normalized_value.text.strip()
        if text:
            return text
    return _safe_text(entity)


def _extract_line_items(entities: List[documentai.Document.Entity]) -> List[Dict[str, Any]]:
    items = []
    for entity in entities:
        if entity.type_ not in {"line_item", "item"}:
            continue

        item = {
            "description": None,
            "product_code": None,
            "quantity": None,
            "unit_price": None,
            "amount": None,
            "currency": None,
            "raw": _safe_text(entity),
        }

        for prop in entity.properties:
            ptype = prop.type_
            if ptype in {"line_item/description", "description", "item_description"}:
                item["description"] = _text_from_entity(prop)
            elif ptype in {"line_item/product_code", "product_code", "sku"}:
                item["product_code"] = _text_from_entity(prop)
            elif ptype in {"line_item/quantity", "quantity"}:
                item["quantity"] = _normalize_number(_text_from_entity(prop))
            elif ptype in {"line_item/unit_price", "unit_price"}:
                item["unit_price"] = _money_from_entity(prop)
            elif ptype in {"line_item/amount", "amount", "line_item/total_amount"}:
                item["amount"] = _money_from_entity(prop)
            elif ptype in {"line_item/currency", "currency"}:
                item["currency"] = _text_from_entity(prop)

        items.append(item)
    return items


def _extract_tax_details(entities: List[documentai.Document.Entity]) -> List[Dict[str, Any]]:
    details = []
    for entity in entities:
        if entity.type_ not in {"tax", "tax_detail"}:
            continue

        detail = {
            "label": _safe_text(entity),
            "rate": None,
            "amount": None,
        }

        for prop in entity.properties:
            if prop.type_ in {"tax_rate", "rate"}:
                detail["rate"] = _normalize_number(_text_from_entity(prop))
            elif prop.type_ in {"tax_amount", "amount"}:
                detail["amount"] = _money_from_entity(prop)

        if detail["label"] or detail["rate"] is not None or detail["amount"] is not None:
            details.append(detail)
    return details


def normalize_expense_fields(
    file_bytes: bytes,
    mime_type: str,
    *,
    project_id: Optional[str] = None,
    location: Optional[str] = None,
    processor_id: Optional[str] = None,
) -> Dict[str, Any]:
    project_id = project_id or os.environ["GOOGLE_CLOUD_PROJECT"]
    location = location or os.environ.get("DOCAI_LOCATION", "us")
    processor_id = processor_id or os.environ["DOCAI_PROCESSOR_ID"]

    endpoint = f"{location}-documentai.googleapis.com"
    client = documentai.DocumentProcessorServiceClient(
        client_options=ClientOptions(api_endpoint=endpoint)
    )

    name = client.processor_path(project_id, location, processor_id)
    request = documentai.ProcessRequest(
        name=name,
        raw_document=documentai.RawDocument(content=file_bytes, mime_type=mime_type),
    )
    result = client.process_document(request=request)
    doc = result.document

    normalized = _deep_copy_schema()
    normalized["document_type"] = "expense"

    entities = list(doc.entities)
    normalized["raw_entities"] = [_entity_to_raw(e) for e in entities]
    normalized["line_items"] = _extract_line_items(entities)
    normalized["tax_details"] = _extract_tax_details(entities)

    for entity in entities:
        entity_type = entity.type_
        if entity_type in {"line_item", "item", "tax", "tax_detail"}:
            continue

        target_key = ENTITY_KEY_MAP.get(entity_type)
        if not target_key:
            continue

        if target_key in {"subtotal", "tax", "tip", "shipping", "discount", "total", "amount_paid", "balance_due"}:
            value = _money_from_entity(entity)
            if value is not None:
                normalized[target_key] = value
        elif target_key in {"invoice_date", "due_date"}:
            value = _date_from_entity(entity)
            if value:
                normalized[target_key] = value
        elif target_key == "merchant_address":
            address_text = _text_from_entity(entity)
            normalized["merchant_address"] = _extract_address_parts(address_text)
        else:
            value = _text_from_entity(entity)
            if value:
                normalized[target_key] = value

        if not normalized["currency"] and entity.normalized_value and getattr(entity.normalized_value, "money_value", None):
            normalized["currency"] = getattr(entity.normalized_value.money_value, "currency_code", None)

    if not normalized["currency"]:
        for entity in entities:
            if entity.normalized_value and getattr(entity.normalized_value, "money_value", None):
                normalized["currency"] = getattr(entity.normalized_value.money_value, "currency_code", None)
                if normalized["currency"]:
                    break

    return normalized
